// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(uint256 arbitrary) public {
        bool ok;
        try c.version() returns (string memory s) {
            bytes memory b = bytes(s);
            if (b.length == 0) {
                ok = false;
            } else {
                ok = (b[0] != bytes1(uint8(0x76)));
            }
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
